      <div className="mt-6 flex justify-end gap-2">
        <button type="button" autoFocus onClick={onClose} className="rounded-md px-4 py-2 text-sm font-medium text-slate-700 hover:bg-slate-100">Cancel</button>
        <button type="button" onClick={onConfirm} className="rounded-md bg-red-600 px-4 py-2 text-sm font-medium text-white hover:bg-red-700">Delete</button>
      </div>
    </Modal>
  )
}

