  await expect(page.getByTestId('count-doing')).toHaveText('4 / 3')
  await shot(page, 'wip')
  await card(page, 'One').getByLabel(/Move .* to column/).selectOption('done')
  await expect(page.getByRole('alert')).toHaveCount(0)
