test('card titles in Done are struck through', async ({ page }) => {
  await seed(page, [
    { id: '1', title: 'Open task', column: 'todo' },
    { id: '2', title: 'Busy task', column: 'doing' },
    { id: '3', title: 'Finished task', column: 'done' },
